def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    events = []
    for start, end in meetings:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    if not events:
        return 0
    events.sort()
    active = 0
    total = 0
    i = 0
    n = len(events)
    while i < n:
        t = events[i][0]
        while i < n and events[i][0] == t:
            active += events[i][1]
            i += 1
        if i < n and active >= k:
            total += events[i][0] - t
    return total
